import torch
import torch.nn as nn

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA operators for Swish activation.
    Uses element-wise addition for batch normalization and custom Swish activation.
    """

    def __init__(self) -> None:
        super().__init__()

        # Custom CUDA operator for Swish activation
        self.swish = torch.nn.functional.swish

        # Custom kernel for batch normalization (element-wise scaling and shifting)
        self.batch_norm_kernel = """
            // Custom CUDA kernel for element-wise batch normalization
            __global__ void batch_norm_kernel(const float* input, int size) {
                int idx = blockIdx.x * blockDim.x + threadIdx.x;
                if (idx < size) {
                    float sum_val = 0.0f;
                    for (int i = 0; i < size; i++) {
                        sum_val += input[idx + i];
                    }
                    input[idx] /= sum_val;
                    input[idx] += sum_val;
                }
            }
        """

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Swish activation to the input tensor.

        Args:
            x (torch.Tensor): Input tensor of any shape.

        Returns:
            torch.Tensor: Output tensor with Swish applied, same shape as input.
        """
        # Apply batch normalization
        normalized_x = self.batch_norm_kernel(x.data(), x.size())

        # Apply Swish activation
        return self.swish(normalized_x)
